/**
 * Resolves the pages the app actually serves for alerts, digests and search hits.
 * Callers pass ids; this module is the only place those ids become hrefs.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

async function slugFor(orgId: OrgId): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? null;
}

/** Issue page in its workspace and project: `/org/projects/proj/issues/12`. */
export async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const slug = await slugFor(orgId);
  if (!slug) return "/";

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(slug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(slug);

  return issuePath(slug, project.slug, issue.number);
}

/** Project page: `/org/projects/proj`. */
export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const slug = await slugFor(orgId);
  if (!slug) return "/";

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project) return orgPath(slug, "projects");

