import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";
import type { PermissionAction } from "@/types/permission";

/** Writes that refuse because the plan has no room, and that tell the owner. */
const REFUSAL_RESOURCES: ReadonlySet<LimitedResource> = new Set([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "webhooks",
]);

function planLimitTitle(resource: LimitedResource): string {
  return `Plan limit reached: ${resource}`;
}

function denied(
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
): PermissionDeniedError {
  return new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "notification",
    reason: "denied_by_role",
  });
}

/** Inboxes and preferences belong to one member, whatever their role. */
function assertOwnRecipient(
  actor: Actor,
  recipientId: UserId,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
): void {
  if (recipientId !== actor.userId) throw denied(action);
}

