      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The welcome goes to the person who joined; the owner sees them on the
  // members page anyway.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [payload.userId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: "/settings/members",
      actorId: null,
    });
  });
}

input.new_string:
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issueHref(payload.orgId, payload.issueId);

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await ownerUserIds(payload.orgId);
    const recipients = owners.filter((userId) => userId !== payload.userId);
    await notify(payload.orgId, "member_joined", recipients, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: await settingsHref(payload.orgId, "members"),
      actorId: payload.userId,
    });
  });

  subscribe("billing.limit_exceeded", async (payload) => {
    if (!REFUSAL_RESOURCES.has(payload.resource)) return;

    const owners = await ownerUserIds(payload.orgId);
    const title = planLimitTitle(payload.resource);
    const href = await settingsHref(payload.orgId, "billing");

    for (const ownerId of owners) {
      const pending = await notificationRepo.hasUnreadWithTitle(
        payload.orgId,
        ownerId,
        "plan_limit_reached",
        title,
      );
      if (pending) continue;

      await notify(payload.orgId, "plan_limit_reached", [ownerId], {
        title,
        body: `The ${payload.resource} limit of ${payload.limit} has been reached (${payload.used} in use).`,
        href,
        // The owner is told even when they are the one who hit the limit.
        actorId: null,
      });
    }
  });
}

/** Active owners of the workspace. Falls back to the org's recorded owner. */
async function ownerUserIds(orgId: OrgId): Promise<readonly UserId[]> {
  const listed = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: "active",
    limit: 25,
    cursor: null,
  });
  const ids = listed.items.map((member) => member.userId);
  if (ids.length > 0) return ids;

  const org = await orgRepo.findOrgById(orgId);
  return org ? [org.ownerId] : [];
}

