/**
 * Announces that a write was refused because the plan has no room left.
 * The notification fan-out tells the workspace owner; a recount must not call this.
 */
export async function recordLimitRefusal(
  orgId: OrgId,
  resource: LimitedResource,
  limit: number,
  used: number,
  actorId: UserId | null,
): Promise<void> {
  await emit("billing.limit_exceeded", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit,
    used,
  });
}

