input.new_string:
export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  // Role never widens this: an owner listing someone else's inbox is refused
  // the same way a viewer is. Tenant scope is checked first so a cross-org
  // read is a tenant error, not a permission error.
  assertOwnRecipient(actor, input.recipientId, "notification:read");
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.listNotifications(input);
}

