/** Rows the inbox can show: delivery included the in-app channel. */
function deliveredInApp() {
  return like(notifications.channels, '%"in_app"%');
}

/**
 * An alert the member has switched off for in-app stays out of the inbox,
 * even when the row was stored with that channel or still goes out by email.
 * No preference row means the default, which is in-app on.
 */
function inAppStillEnabled() {
  const db = getDb();
  return notExists(
    db
      .select({ kind: notificationPreferences.kind })
      .from(notificationPreferences)
      .where(
        and(
          eq(notificationPreferences.orgId, notifications.orgId),
          eq(notificationPreferences.userId, notifications.recipientId),
          eq(notificationPreferences.kind, notifications.kind),
          eq(notificationPreferences.inApp, false),
        ),
      ),
  );
}

